   optionNotes:{A:{why:"The first line still contains `{{c2}}`.",cause:"Thinking `substitute` fills `{{c2}}`."},B:{why:"`$c1` is replaced in the first line.",cause:"Thinking substitute does nothing."},C:{why:"First line keeps `{{c2}}`; second is fully filled."},D:{why:"Template does not touch `{{c2}}` at all, so it never becomes `{{diploma}}`.",cause:"Mixing the two syntaxes."}},
