   optionNotes:{A:{why:"No route for `/`; the view reads no query string.",cause:"Thinking query values fill placeholders."},B:{why:"Same as A.",cause:"Thinking query values fill placeholders."},C:{why:"Wrong order: `red` is not an int.",cause:"Ignoring the rule's order."},D:{why:"Right order and types."}},
